# extract_emails :: 'Contact alice@example.com or bob@foo.co.uk.'
import re

def extract_emails(text):
    return re.findall(r"[\w.+-]+@[\w-]+\.[\w.-]+", text)

if __name__ == "__main__":
    print(extract_emails('Contact alice@example.com or bob@foo.co.uk.'))

